<script setup>
import StatisticsSelect from "./StatisticsSelect.vue"
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {Bar} from 'vue-chartjs'
import {Chart as ChartJS,BarController,LineController,CategoryScale,LinearScale,BarElement,LineElement,PointElement,Tooltip,Legend} from 'chart.js'
import * as XLSX from 'xlsx'
import api from '../../../../utils/api'
ChartJS.register(BarController,LineController,CategoryScale,LinearScale,BarElement,LineElement,PointElement,Tooltip,Legend)
const mode=ref('month'),periods=ref([]),rows=ref([]),fixed=ref([]),loading=ref(false),error=ref(''),fixedError=ref(''),fixedLoading=ref(false)
const search=ref(''),growthFilter=ref('all'),fixedSearch=ref(''),fixedFilter=ref('all'),showGrowth=ref(true)
let requestVersion=0,controller,timer,fixedController
const now=new Date(),year=now.getFullYear(),month=now.getMonth()+1,quarter=Math.floor((month-1)/3)+1
const yearOptions=Array.from({length:year-1999},(_,i)=>year-i)
const pad=n=>String(n).padStart(2,'0')
const money=n=>Number(n||0).toLocaleString('vi-VN',{maximumFractionDigits:0})+' đ'
const number=n=>Number(n||0).toLocaleString('vi-VN')
const percent=n=>n==null?'Không có cơ sở so sánh':(n>0?'+':'')+Number(n).toLocaleString('vi-VN',{maximumFractionDigits:2})+'%'
function keyFor(date){return mode.value==='month'?date.getFullYear()+'-'+pad(date.getMonth()+1):mode.value==='quarter'?date.getFullYear()+'-Q'+(Math.floor(date.getMonth()/3)+1):String(date.getFullYear())}
function periodKey(p){return mode.value==='month'?p.year+'-'+pad(p.part):mode.value==='quarter'?p.year+'-Q'+p.part:String(p.year)}
function defaults(){const first=new Date(year,month-1,1),previous=new Date(first);if(mode.value==='month')previous.setMonth(previous.getMonth()-1);else if(mode.value==='quarter')previous.setMonth(previous.getMonth()-3);else previous.setFullYear(previous.getFullYear()-1);return [previous,first].map((d,i)=>({id:Date.now()+i,year:d.getFullYear(),part:mode.value==='quarter'?Math.floor(d.getMonth()/3)+1:d.getMonth()+1}))}
function resetPeriods(){periods.value=defaults();search.value='';growthFilter.value='all'}
function addPeriod(){if(periods.value.length>=12)return;let d=new Date(year,month-1,1);const keys=new Set(periods.value.map(periodKey));while(keys.has(keyFor(d))){if(mode.value==='month')d.setMonth(d.getMonth()-1);else if(mode.value==='quarter')d.setMonth(d.getMonth()-3);else d.setFullYear(d.getFullYear()-1)}periods.value.push({id:Date.now(),year:d.getFullYear(),part:mode.value==='quarter'?Math.floor(d.getMonth()/3)+1:d.getMonth()+1})}
const validation=computed(()=>{
 if(periods.value.length<2)return 'Chọn ít nhất 2 kỳ để so sánh.'
 const keys=periods.value.map(periodKey);if(new Set(keys).size!==keys.length)return 'Các kỳ so sánh không được trùng nhau.'
 for(const p of periods.value){if(!Number.isInteger(Number(p.year))||p.year<2000||p.year>2100)return 'Năm phải từ 2000 đến 2100.';if(p.year>year||(p.year===year&&mode.value==='month'&&p.part>month)||(p.year===year&&mode.value==='quarter'&&p.part>quarter))return 'Không chọn kỳ chưa bắt đầu.'}
 return ''
})
async function load(){
 const version=++requestVersion;controller?.abort();error.value='';rows.value=[]
 if(validation.value){loading.value=false;return}
 controller=new AbortController();loading.value=true
 try{const response=await api.post('/thong-ke-tong-hop/so-sanh-tuy-chon',{kind:mode.value,periods:periods.value.map(periodKey)},{signal:controller.signal,timeout:15000});if(version!==requestVersion)return;if(!response.data?.success)throw Error('Không tải được dữ liệu so sánh');rows.value=response.data.data||[]}
 catch(e){if(version===requestVersion&&e.code!=='ERR_CANCELED')error.value=e.response?.data?.message||'Không tải được so sánh. Vui lòng thử lại.'}
 finally{if(version===requestVersion)loading.value=false}
}
async function loadFixed(){fixedController?.abort();fixedController=new AbortController();fixedLoading.value=true;fixedError.value='';try{const response=await api.get('/thong-ke-tong-hop/chu-ky',{signal:fixedController.signal,timeout:15000});if(!response.data?.success)throw Error('Không tải được các mốc thời gian');fixed.value=response.data.data||[]}catch(e){if(e.code!=='ERR_CANCELED')fixedError.value=e.response?.data?.message||'Không tải được các mốc thời gian.'}finally{fixedLoading.value=false}}
function filterRows(data,query,filter){return data.filter(r=>String(r.period).toLocaleLowerCase('vi-VN').includes(query.trim().toLocaleLowerCase('vi-VN'))&&(filter==='all'||filter==='up'&&r.growth>0||filter==='down'&&r.growth<0||filter==='none'&&r.growth==null||filter==='flat'&&r.growth!=null&&Number(r.growth)===0))}
const filtered=computed(()=>filterRows(rows.value,search.value,growthFilter.value))
const filteredFixed=computed(()=>filterRows(fixed.value,fixedSearch.value,fixedFilter.value))
const chart=computed(()=>({labels:rows.value.map(r=>r.period),datasets:[{type:'bar',label:'Doanh thu (đ)',data:rows.value.map(r=>r.revenue),backgroundColor:'#2196d2',borderRadius:6,maxBarThickness:66,yAxisID:'revenue'},...(showGrowth.value?[{type:'line',label:'Tăng trưởng so với kỳ được chọn trước (%)',data:rows.value.map(r=>r.growth),borderColor:'#ed9b29',backgroundColor:'#ed9b29',pointRadius:5,borderWidth:3,tension:.2,yAxisID:'growth',spanGaps:false}]:[])]}))
const options=computed(()=>({responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:ctx=>ctx.dataset.type==='line'?'Tăng trưởng: '+percent(ctx.raw):'Doanh thu: '+money(ctx.raw),afterBody:items=>{const row=rows.value[items[0]?.dataIndex];return row?.growthBase?'So với '+row.growthBase:''}}}},scales:{x:{title:{display:true,text:mode.value==='month'?'Tháng / năm':mode.value==='quarter'?'Quý / năm':'Năm'},grid:{display:false}},revenue:{position:'left',beginAtZero:true,title:{display:true,text:'Doanh thu (triệu đồng)'},ticks:{callback:v=>Number(v/1000000).toLocaleString('vi-VN',{maximumFractionDigits:2})}},growth:{display:showGrowth.value,position:'right',title:{display:true,text:'Tăng trưởng (%)'},grid:{drawOnChartArea:false},ticks:{callback:v=>number(v)+'%'}}}}))
function exportRows(data,name){const sheet=XLSX.utils.json_to_sheet(data.map(r=>({'Kỳ':r.period,'Doanh thu (đ)':Number(r.revenue||0),'Đơn hoàn thành':Number(r.orders||0),'Giá trị đơn TB (đ)':Number(r.aov||0),'Tăng trưởng (%)':r.growth??'Không có cơ sở so sánh','So với':r.growthBase||'Kỳ trước theo lịch'})));sheet['!cols']=[{wch:24},{wch:24},{wch:20},{wch:24},{wch:28},{wch:24}];const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'So lieu');XLSX.writeFile(book,name+'.xlsx')}
watch(mode,resetPeriods)
watch(periods,()=>{++requestVersion;controller?.abort();rows.value=[];loading.value=!validation.value;clearTimeout(timer);timer=setTimeout(load,300)},{deep:true})
resetPeriods();load();loadFixed()
onBeforeUnmount(()=>{++requestVersion;clearTimeout(timer);controller?.abort();fixedController?.abort()})
</script>
<template>
 <div class="comparison-workspace">
  <article class="compare-card">
   <header><div><h2>So sánh doanh thu giữa các kỳ</h2><p>Chọn các kỳ muốn đối chiếu. Kỳ hiện tại hiển thị số liệu tạm tính.</p></div><StatisticsSelect v-model="mode" aria-label="Nhóm kỳ so sánh"><option value="month">Theo tháng</option><option value="quarter">Theo quý</option><option value="year">Theo năm</option></StatisticsSelect></header>
   <div class="period-picker"><div v-for="(period,index) in periods" :key="period.id" class="period-choice"><span class="period-number">{{index+1}}</span><label>Năm<StatisticsSelect v-model="period.year" aria-label="Năm so sánh"><option v-for="value in yearOptions" :key="value" :value="value">{{value}}</option></StatisticsSelect></label><label v-if="mode!=='year'">{{mode==='month'?'Tháng':'Quý'}}<StatisticsSelect v-model.number="period.part" :aria-label="mode==='month'?'Tháng so sánh':'Quý so sánh'"><option v-for="part in mode==='month'?12:4" :key="part" :value="part">{{mode==='month'?'Tháng':'Quý'}} {{part}}</option></StatisticsSelect></label><button type="button" class="remove-period" :disabled="periods.length<=2" :aria-label="'Bỏ kỳ '+(index+1)" @click="periods.splice(index,1)">−</button></div><button type="button" class="add-period" :disabled="periods.length>=12" @click="addPeriod">+ Thêm kỳ</button></div>
   <p v-if="validation" class="compare-error" role="alert">{{validation}}</p>
   <p class="comparison-explanation">Các kỳ được sắp theo thời gian. Đường tăng trưởng so với kỳ được chọn ngay trước đó; kỳ đầu không tính %. Khi kỳ trước có doanh thu bằng 0, tỷ lệ không có cơ sở so sánh.</p>
   <div class="chart-toolbar"><label><input v-model="showGrowth" type="checkbox">Hiện đường tăng trưởng (%)</label><button type="button" :disabled="loading||!!validation" @click="load">Tải lại</button></div>
   <p v-if="loading" class="compare-empty" role="status">Đang tải so sánh…</p><p v-else-if="error" class="compare-error" role="alert">{{error}}</p><div v-else-if="rows.length&&!validation" class="compare-chart"><Bar :data="chart" :options="options"/></div>
  </article>
  <article class="compare-card"><header><div><h2>Bảng số liệu đối chiếu</h2><p>Các kỳ đã chọn phía trên · doanh thu từ đơn hoàn thành</p></div><button type="button" :disabled="loading||!filtered.length" @click="exportRows(filtered,'so-sanh-cac-ky')">Xuất Excel</button></header>
   <div class="compare-filters"><input v-model="search" type="search" placeholder="Tìm kỳ, ví dụ Tháng 10…" aria-label="Tìm kỳ đối chiếu"><StatisticsSelect v-model="growthFilter" aria-label="Lọc tăng trưởng đối chiếu"><option value="all">Tất cả tăng trưởng</option><option value="up">Tăng trưởng dương</option><option value="down">Tăng trưởng âm</option><option value="flat">Không thay đổi</option><option value="none">Chưa có cơ sở so sánh</option></StatisticsSelect><button type="button" @click="search='';growthFilter='all'">Đặt lại</button></div>
   <div class="compare-table"><table><thead><tr><th>Kỳ</th><th>Doanh thu</th><th>Đơn hoàn thành</th><th>Giá trị đơn TB</th><th>Tăng trưởng</th><th>So với</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.key"><td>{{row.period}}<small v-if="row.temporary">Tạm tính</small></td><td class="revenue">{{money(row.revenue)}}</td><td>{{number(row.orders)}}</td><td>{{money(row.aov)}}</td><td :class="{positive:row.growth>0,negative:row.growth<0}">{{percent(row.growth)}}</td><td>{{row.growthBase||'—'}}</td></tr><tr v-if="!filtered.length"><td colspan="6" class="compare-empty">{{loading?'Đang tải…':'Không có kỳ phù hợp.'}}</td></tr></tbody></table></div>
  </article>
  <article class="compare-card"><header><div><h2>Các mốc thời gian hiện tại</h2><p>Hôm nay, tuần, tháng, năm hiện tại; tăng trưởng so với kỳ liền trước theo lịch.</p></div><button type="button" :disabled="fixedLoading||!filteredFixed.length" @click="exportRows(filteredFixed,'cac-moc-hien-tai')">Xuất Excel</button></header>
   <div class="compare-filters"><input v-model="fixedSearch" type="search" placeholder="Tìm mốc thời gian…" aria-label="Tìm mốc thời gian"><StatisticsSelect v-model="fixedFilter" aria-label="Lọc tăng trưởng mốc thời gian"><option value="all">Tất cả tăng trưởng</option><option value="up">Tăng trưởng dương</option><option value="down">Tăng trưởng âm</option><option value="flat">Không thay đổi</option><option value="none">Chưa có cơ sở so sánh</option></StatisticsSelect><button type="button" @click="fixedSearch='';fixedFilter='all'">Đặt lại</button></div>
   <p v-if="fixedError" class="compare-error" role="alert">{{fixedError}} <button type="button" @click="loadFixed">Thử lại</button></p><div class="compare-table"><table><thead><tr><th>Mốc thời gian</th><th>Doanh thu</th><th>Đơn hoàn thành</th><th>Giá trị đơn TB</th><th>Tăng trưởng</th></tr></thead><tbody><tr v-for="row in filteredFixed" :key="row.period"><td>{{row.period}}</td><td class="revenue">{{money(row.revenue)}}</td><td>{{number(row.orders)}}</td><td>{{money(row.aov)}}</td><td :class="{positive:row.growth>0,negative:row.growth<0}">{{percent(row.growth)}}</td></tr><tr v-if="!filteredFixed.length"><td colspan="5" class="compare-empty">{{fixedLoading?'Đang tải…':'Không có mốc phù hợp.'}}</td></tr></tbody></table></div>
  </article>
 </div>
</template>
<style scoped>
.comparison-workspace{display:grid;gap:22px;color:#23475f}.compare-card{background:white;border:1px solid #dce9f1;border-radius:16px;box-shadow:0 2px 5px #163f5b06;overflow:hidden}.compare-card header{padding:24px;display:flex;align-items:center;justify-content:space-between;gap:16px}.compare-card h2{font-size:17px;margin:0 0 9px}.compare-card p{color:#8a9eac;font-size:12px;line-height:1.7;margin:0}.compare-card button,.compare-card input:not([type=checkbox]),.compare-card select{font:inherit;font-size:12px;min-width:0;max-width:100%;height:40px;border:1px solid #d3e3ee;border-radius:8px;background:white;color:#4e7188;padding:0 12px}.compare-card button{cursor:pointer;color:#168fce}.compare-card button:disabled{opacity:.45;cursor:not-allowed}.period-picker{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;padding:0 24px 18px}.period-choice{display:flex;align-items:flex-end;gap:9px;padding:12px;background:#f7fafc;border:1px solid #e1eaf1;border-radius:11px}.period-choice label{display:flex;flex-direction:column;gap:6px;font-size:11px;color:#7f95a5}.period-choice input{width:85px}.period-choice select{width:105px}.period-number{align-self:center;background:#e6f3fc;color:#168fce;font-size:11px;padding:5px 8px;border-radius:50%}.period-choice .remove-period{color:#c65e68;width:32px;padding:0;font-size:22px}.compare-card .add-period{border-style:dashed;color:#168fce}.compare-card .comparison-explanation{padding:0 24px 15px;color:#7b93a3}.chart-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:0 24px 12px;font-size:12px;color:#7590a2}.chart-toolbar label{display:flex;align-items:center;gap:8px}.compare-chart{height:390px;padding:10px 24px 26px}.compare-filters{display:flex;flex-wrap:wrap;gap:12px;padding:0 24px 20px}.compare-filters input{flex:1;min-width:180px!important;max-width:400px!important}.compare-table{overflow:auto;width:100%}.compare-table table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap;text-align:left}.compare-table th{background:#edf6fb;color:#6c899d;font-size:11px;padding:17px 24px;border-top:1px solid #e1ebf2}.compare-table td{padding:18px 24px;border-top:1px solid #edf3f7;color:#55778c}.compare-table small{display:block;color:#ba8b38;margin-top:6px}.compare-table .revenue{font-weight:700;color:#168fce}.compare-table .positive{color:#22946d}.compare-table .negative{color:#c95d6d}.compare-card .compare-empty{text-align:center;padding:35px;color:#8da1ae}.compare-card .compare-error{padding:15px 24px;color:#bf5963}@media(max-width:700px){.compare-card header{padding:18px;flex-wrap:wrap}.period-picker{padding:0 18px 16px}.period-choice{flex:1;min-width:220px}.compare-card .comparison-explanation{padding:0 18px 15px}.compare-filters{padding:0 18px 18px}.compare-filters select{width:100%}.compare-chart{height:310px;padding:4px 10px 20px}.chart-toolbar{padding:0 18px 12px}}
.period-choice :deep(.statistics-select){min-width:85px;width:105px}.compare-filters :deep(.statistics-select){min-width:195px}.compare-card header :deep(.statistics-select){width:155px;min-width:155px}.period-choice :deep(.select2-container){max-width:100%}@media(max-width:700px){.compare-filters :deep(.statistics-select){width:100%}}
</style>
